function sumTriangleRow(triangle, n) {
  // Get the numbers in the nth row of the triangle
  const numbers = triangle[n - 1];

  // Compute the sum of the numbers in the row
  let sum = 0;
  for (let i = 0; i < numbers.length; i++) {
