// function to generate a random number between min and max (inclusive)
function getRandomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

// function to start the game
function startGame() {
  let min = parseInt(prompt("Enter the minimum number: "));
  let max = parseInt(prompt("Enter the maximum number: "));
  let correctNumber = getRandomInt(min, max);
  let guess;

  // loop until the correct number is guessed
  while (guess !== correctNumber) {
    guess = getRandomInt(min, max);
    let feedback = prompt(`Is your number ${guess}? Enter "more" or "less" or "correct"`);
    if (feedback === "more") {
      max = guess - 1;
    } else if (feedback === "less") {
      min = guess + 1;
    } else if (feedback !== "correct") {
      alert("Invalid input. Please enter 'more', 'less', or 'correct'.");
    }
  }
  alert(`I guessed your number ${correctNumber}!`);
}

// start the game when the page loads
startGame();
