The error you're encountering (`Cannot read properties of null (reading 'addEventListener')`) occurs because the JavaScript code is trying to access elements (like `draggableSquare`, `targetSquare`, or `resetButton`) that do **not exist in the DOM** at the time the script runs. This is a common issue when the script runs before the HTML elements are fully loaded.

---

### ✅ **Solution: Ensure Elements Exist Before Accessing Them**

To fix this, you need to **ensure the script runs only after the DOM is fully loaded**. Here's how to do it:

---

### 🔧 **Updated JavaScript (Corrected Code)**

```javascript
document.addEventListener("DOMContentLoaded", function () {
    let draggableSquare = document.getElementById("draggable-square");
    let targetSquare = document.getElementById("target-square");
    let resetButton = document.getElementById("reset-button");

    if (!draggableSquare || !targetSquare || !resetButton) {
        console.error("One or more elements not found in the DOM.");
        return;
    }

    draggableSquare.addEventListener("mousedown", function () {
        draggableSquare.classList.add("clicked");
        draggableSquare.style.position = 'absolute';
        draggableSquare.style.zIndex = 1000;

        function moveAt(pageX, pageY) {
            draggableSquare.style.left = pageX - draggableSquare.offsetWidth / 2 + 'px';
            draggableSquare.style.top = pageY - draggableSquare.offsetHeight / 2 + 'px';
        }
        moveAt(event.pageX, event.pageY);

        function onMouseMove(event) {
            moveAt(event.pageX, event.pageY);
        }
        document.addEventListener('mousemove', onMouseMove);

        draggableSquare.onmouseup = function () {
            document.removeEventListener('mousemove', onMouseMove);
            draggableSquare.onmouseup = null;
        };
    });

    draggableSquare.addEventListener("mouseover", function () {
        if (draggableSquare.classList.contains("clicked")) {
            targetSquare.classList.add("overlapped");
        }
    });

    draggableSquare.addEventListener("mouseout", function () {
        if (draggableSquare.classList.contains("clicked")) {
            targetSquare.classList.remove("overlapped");
        }
    });

    resetButton.addEventListener("click", function () {
        draggableSquare.classList.remove("clicked");
        targetSquare.classList.remove("overlapped");
    });
});
```

---

### 📝 **Key Fixes and Improvements:**

1. **DOMContentLoaded Event**  
   The script now waits for the entire DOM to load before accessing elements. This ensures that `getElementById` will not return `null`.

2. **Error Check**  
   Added a check to verify that all elements (`draggableSquare`, `targetSquare`, `resetButton`) exist in the DOM. If any are missing, it logs an error.

3. **Corrected Event Handling**  
   The `mousedown` event now correctly adds the `clicked` class and starts dragging the square. The `mousemove` and `mouseup` events are properly handled to move and release the square.

4. **CSS Integration**  
   Ensure your CSS includes the necessary styles for the squares and their states (e.g., `white-square`, `gray-square`, `clicked`, `overlapped`).

---

